ldi a, 2 ;первое простое число - 2
st a, 0xff ;выводим
inc a ;следующее 3
loop:
  st a, 0xff ;выводим найденное простое число
  ld d, cursor ;читаем указатель на последнее простое число
  st a, d ;сохраняем число
  inc d ;следующий указатель
  st d, cursor ;сохраняем
  next: ;следующий кандидат на простое число
    inc a
    jz end ;если превысили 255, завершаем программу
    inc a
    ldi d, data ;указатель на простые числа
  loop2: ;перебор делителей (в роли делителей выступают найденные простые числа)
    ld c, d ;читаем число
    inc d ;следующий делитель
    mov b, a ;копируем кандидата
    shr b ;делим на 2
    sub b, c ;если делитель больше половины числа, значит простое число найдено
    jc loop
    mov b, a ;копируем обратно
    div_loop: ;делим
      sub b, c
      jz next ;если получили 0, значит число не простое и переходим к следующему кандидату
      jnc div_loop ;если число больше 0, продолжаем делить
    jmp loop2 ;если в результате деления 0 не получился, проверяем дальше
end:
  hlt ;конец
cursor db data ;указатель на последнее число
data db 0 ;простые числа


